static void
test_filter_rk3(bool cellwise_const)
{
  struct gkyl_gk inp = {
    .name = "ctest_filter_rk3",
    .cdim = 1,
    .lower = {-1.0}, .upper = {1.0}, .cells = {2},
    .poly_order = 1, .basis_type = GKYL_BASIS_MODAL_SERENDIPITY,
    .geometry = {
      .geometry_id = GKYL_GEOMETRY_MAPC2P,
      .mapc2p = identity_map, .bfield_func = unit_profile,
    },
    .num_periodic_dir = 1, .periodic_dirs = {0},
    .num_species = 1,
    .species = {{
      .name = "test", .charge = 1.0, .mass = 1.0, .vdim = 2,
      .lower = {-2.0, 0.0}, .upper = {2.0, 2.0}, .cells = {2, 2},
      .polarization_density = 1.0,
      .projection = {.proj_id = GKYL_PROJ_FUNC, .func = unit_profile},
      .damping = {.type = GKYL_GK_DAMPING_LOW_PASS_FILTER, .rate_const = 2.0,
        .cellwise_const = cellwise_const},
      .time_rate_multiplier = {.num_multipliers = 1, .multiplier = {{
        .type = GKYL_GK_FDOT_MULTIPLIER_CONSTANT,
        .cellwise_const = true, .time_dilation_scale_const = 0.25,
      }}},
    }},
    .field = {.is_static = true, .zero_init_field = true, .kperpSq = 1.0},
  };
  gkyl_gyrokinetic_app *app = gkyl_gyrokinetic_app_new(&inp);
  gkyl_gyrokinetic_app_apply_ic(app, 0.0);
  struct gk_species *gks = &app->species[0];
  gkyl_array_clear(gks->f, 3.0);
  gkyl_array_clear(gks->damping.fbar, 1.0);
  double decay = 1.0, high_decay = 1.0;
  for (int step = 0; step < 3; ++step) {
    struct gkyl_update_status st = gkyl_gyrokinetic_update(app, 0.1);
    TEST_CHECK(st.success);
    double arg = -2.0 * 0.25 * 2.0 * st.dt_actual;
    decay *= 1.0 + arg + arg * arg / 2.0 + arg * arg * arg / 6.0;
    arg *= 0.5;
    high_decay *= 1.0 + arg + arg * arg / 2.0 + arg * arg * arg / 6.0;
    struct gkyl_range_iter iter;
    gkyl_range_iter_init(&iter, &gks->local);
    while (gkyl_range_iter_next(&iter)) {
      long loc = gkyl_range_idx(&gks->local, iter.idx);
      const double *fval = gkyl_array_cfetch(gks->f, loc);
      const double *bar = gkyl_array_cfetch(gks->damping.fbar, loc);
      for (int k = 0; k < gks->damping.fbar->ncomp; ++k) {
        TEST_CHECK(gkyl_compare(fval[k] + bar[k], 4.0, 1e-12));
        TEST_CHECK(gkyl_compare(fval[k] - bar[k], 2.0 * decay, 1e-12));
      }
      for (int k = gks->damping.fbar->ncomp; k < gks->f->ncomp; ++k) {
        TEST_CHECK(gkyl_compare(fval[k], 3.0 * high_decay, 1e-12));
      }
    }
  }
  gkyl_gyrokinetic_app_release(app);
}

static void test_rk3_same_basis(void) { test_filter_rk3(false); }
static void test_rk3_cellwise_const(void) { test_filter_rk3(true); }

